import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('SingleChildScrollView'),
        ),
        body: SingleChildScrollView(
          // Отступы внутри прокручиваемой области
          padding: const EdgeInsets.all(16),

          // Физика прокрутки (отскок как на iOS)
          physics: const BouncingScrollPhysics(),

          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Заголовок
              const Text(
                'Форма регистрации',
                style: TextStyle(
                  fontSize: 24,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 20),

              // Поля формы
              const TextField(
                decoration: InputDecoration(
                  labelText: 'Имя',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.person),
                ),
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Email',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.email),
                ),
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Телефон',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.phone),
                ),
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Пароль',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.lock),
                ),
                obscureText: true,
              ),
              const SizedBox(height: 16),

              const TextField(
                decoration: InputDecoration(
                  labelText: 'Повторите пароль',
                  border: OutlineInputBorder(),
                  prefixIcon: Icon(Icons.lock_outline),
                ),
                obscureText: true,
              ),
              const SizedBox(height: 16),

              // Описание
              Container(
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: Colors.blue.shade50,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: const Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Условия использования',
                      style: TextStyle(fontWeight: FontWeight.bold),
                    ),
                    SizedBox(height: 8),
                    Text(
                      'Регистрируясь, вы соглашаетесь с нашими условиями использования и политикой конфиденциальности. Мы заботимся о безопасности ваших данных.',
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 24),

              // Кнопка
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: () {},
                  style: ElevatedButton.styleFrom(
                    padding: const EdgeInsets.all(16),
                  ),
                  child: const Text(
                    'Зарегистрироваться',
                    style: TextStyle(fontSize: 16),
                  ),
                ),
              ),
              const SizedBox(height: 16),

              // Дополнительная информация
              const Center(
                child: Text(
                  'Уже есть аккаунт? Войти',
                  style: TextStyle(color: Colors.blue),
                ),
              ),

              // Дополнительный контент для демонстрации прокрутки
              const SizedBox(height: 40),
              const Divider(),
              const SizedBox(height: 20),
              const Text(
                'Почему выбирают нас?',
                style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 16),

              // Преимущества
              _buildFeatureCard(
                Icons.speed,
                'Быстро',
                'Регистрация занимает меньше минуты',
              ),
              _buildFeatureCard(
                Icons.security,
                'Безопасно',
                'Ваши данные надежно защищены',
              ),
              _buildFeatureCard(
                Icons.support_agent,
                'Поддержка 24/7',
                'Мы всегда готовы помочь',
              ),
            ],
          ),
        ),
      ),
    );
  }

  static Widget _buildFeatureCard(IconData icon, String title, String desc) {
    return Card(
      margin: const EdgeInsets.only(bottom: 12),
      child: ListTile(
        leading: CircleAvatar(
          child: Icon(icon),
        ),
        title: Text(title),
        subtitle: Text(desc),
      ),
    );
  }
}

import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: DefaultTabController(
        length: 3,
        child: Scaffold(
          appBar: AppBar(
            title: const Text('ListView примеры'),
            bottom: const TabBar(
              tabs: [
                Tab(text: 'Простой'),
                Tab(text: 'Builder'),
                Tab(text: 'Separated'),
              ],
            ),
          ),
          body: TabBarView(
            children: [
              // 1. Простой ListView
              _buildSimpleListView(),

              // 2. ListView.builder
              _buildListViewBuilder(),

              // 3. ListView.separated
              _buildListViewSeparated(),
            ],
          ),
        ),
      ),
    );
  }

  // Простой ListView - для маленьких списков
  Widget _buildSimpleListView() {
    return ListView(
      padding: const EdgeInsets.all(16),
      children: const [
        Card(
          child: ListTile(
            leading: Icon(Icons.home, color: Colors.blue),
            title: Text('Главная'),
            subtitle: Text('Вернуться на главный экран'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.person, color: Colors.green),
            title: Text('Профиль'),
            subtitle: Text('Настройки профиля'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.settings, color: Colors.orange),
            title: Text('Настройки'),
            subtitle: Text('Параметры приложения'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.help, color: Colors.purple),
            title: Text('Помощь'),
            subtitle: Text('Часто задаваемые вопросы'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        Card(
          child: ListTile(
            leading: Icon(Icons.info, color: Colors.teal),
            title: Text('О приложении'),
            subtitle: Text('Версия и информация'),
            trailing: Icon(Icons.arrow_forward_ios),
          ),
        ),
        SizedBox(height: 20),
        Center(
          child: Text(
            'Простой ListView создает\nвсе элементы сразу',
            textAlign: TextAlign.center,
            style: TextStyle(color: Colors.grey),
          ),
        ),
      ],
    );
  }

  // ListView.builder - для больших списков
  Widget _buildListViewBuilder() {
    // Имитация данных - 100 контактов
    final contacts = List.generate(
      100,
      (index) => {
        'name': 'Контакт ${index + 1}',
        'phone': '+7 ${700 + index} 123 45 67',
        'avatar': Colors.primaries[index % Colors.primaries.length],
      },
    );

    return ListView.builder(
      padding: const EdgeInsets.all(8),
      // Количество элементов
      itemCount: contacts.length,
      // Функция создания элемента
      itemBuilder: (context, index) {
        final contact = contacts[index];
        return Card(
          child: ListTile(
            leading: CircleAvatar(
              backgroundColor: contact['avatar'] as Color,
              child: Text(
                (contact['name'] as String)[0],
                style: const TextStyle(color: Colors.white),
              ),
            ),
            title: Text(contact['name'] as String),
            subtitle: Text(contact['phone'] as String),
            trailing: IconButton(
              icon: const Icon(Icons.call),
              onPressed: () {},
            ),
          ),
        );
      },
    );
  }

  // ListView.separated - с разделителями
  Widget _buildListViewSeparated() {
    final messages = [
      {'sender': 'Алия', 'text': 'Привет! Как дела?', 'time': '10:30'},
      {'sender': 'Мама', 'text': 'Не забудь позвонить', 'time': '09:15'},
      {'sender': 'Работа', 'text': 'Встреча в 15:00', 'time': 'Вчера'},
      {'sender': 'Данияр', 'text': 'Увидимся завтра!', 'time': 'Вчера'},
      {'sender': 'Банк', 'text': 'Ваш платеж прошел', 'time': 'Пн'},
      {'sender': 'Доставка', 'text': 'Заказ доставлен', 'time': 'Пн'},
      {'sender': 'Асет', 'text': 'Отличный код!', 'time': 'Вс'},
    ];

    return ListView.separated(
      padding: const EdgeInsets.all(8),
      itemCount: messages.length,
      // Разделитель между элементами
      separatorBuilder: (context, index) => const Divider(
        height: 1,
        indent: 72, // Отступ слева (под аватар)
      ),
      // Элемент списка
      itemBuilder: (context, index) {
        final msg = messages[index];
        return ListTile(
          leading: CircleAvatar(
            child: Text(msg['sender']![0]),
          ),
          title: Text(msg['sender']!),
          subtitle: Text(
            msg['text']!,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
          trailing: Text(
            msg['time']!,
            style: const TextStyle(
              color: Colors.grey,
              fontSize: 12,
            ),
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('Горизонтальные списки'),
