  Widget _buildCategoryChip(String label, bool isSelected) {
    return Container(
      margin: const EdgeInsets.symmetric(horizontal: 4),
      child: Chip(
        label: Text(label),
        backgroundColor: isSelected ? Colors.blue : Colors.grey.shade200,
        labelStyle: TextStyle(
          color: isSelected ? Colors.white : Colors.black,
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: DefaultTabController(
        length: 3,
        child: Scaffold(
          appBar: AppBar(
            title: const Text('GridView примеры'),
            bottom: const TabBar(
              tabs: [
                Tab(text: 'Галерея'),
                Tab(text: 'Приложения'),
                Tab(text: 'Товары'),
              ],
            ),
          ),
          body: TabBarView(
            children: [
              // 1. Галерея (как Instagram)
              _buildPhotoGallery(),

              // 2. Сетка приложений (как Play Store)
              _buildAppsGrid(),

              // 3. Товары (как интернет-магазин)
              _buildProductsGrid(),
            ],
          ),
        ),
      ),
    );
  }

  // Галерея фото (как Instagram профиль)
  Widget _buildPhotoGallery() {
    return GridView.builder(
      padding: const EdgeInsets.all(2),
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 3, // 3 колонки как в Instagram
        mainAxisSpacing: 2,
        crossAxisSpacing: 2,
      ),
      itemCount: 30,
      itemBuilder: (context, index) {
        return Container(
          decoration: BoxDecoration(
            image: DecorationImage(
              image: NetworkImage(
                'https://picsum.photos/200/200?random=$index',
              ),
              fit: BoxFit.cover,
            ),
          ),
          child: index % 5 == 0
              ? const Align(
                  alignment: Alignment.topRight,
                  child: Padding(
                    padding: EdgeInsets.all(4),
                    child: Icon(
                      Icons.collections,
                      color: Colors.white,
                      size: 16,
                    ),
                  ),
                )
              : null,
        );
      },
    );
  }

  // Сетка приложений
  Widget _buildAppsGrid() {
    final apps = [
      {'name': 'WhatsApp', 'icon': Icons.chat, 'color': Colors.green},
      {'name': 'Instagram', 'icon': Icons.camera_alt, 'color': Colors.purple},
      {'name': 'YouTube', 'icon': Icons.play_circle, 'color': Colors.red},
      {'name': 'Telegram', 'icon': Icons.send, 'color': Colors.blue},
      {'name': 'TikTok', 'icon': Icons.music_note, 'color': Colors.black},
      {'name': 'Twitter', 'icon': Icons.flutter_dash, 'color': Colors.lightBlue},
      {'name': 'Gmail', 'icon': Icons.email, 'color': Colors.red.shade700},
      {'name': 'Maps', 'icon': Icons.map, 'color': Colors.green.shade700},
      {'name': 'Chrome', 'icon': Icons.public, 'color': Colors.orange},
      {'name': 'Calendar', 'icon': Icons.calendar_today, 'color': Colors.blue.shade700},
      {'name': 'Photos', 'icon': Icons.photo_library, 'color': Colors.amber},
      {'name': 'Settings', 'icon': Icons.settings, 'color': Colors.grey},
    ];

    return GridView.builder(
      padding: const EdgeInsets.all(16),
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 4, // 4 колонки
        mainAxisSpacing: 16,
        crossAxisSpacing: 16,
        childAspectRatio: 0.8, // Соотношение сторон
      ),
      itemCount: apps.length,
      itemBuilder: (context, index) {
        final app = apps[index];
        return Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Container(
              width: 56,
              height: 56,
              decoration: BoxDecoration(
                color: app['color'] as Color,
                borderRadius: BorderRadius.circular(12),
              ),
              child: Icon(
                app['icon'] as IconData,
                color: Colors.white,
                size: 28,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              app['name'] as String,
              style: const TextStyle(fontSize: 11),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ],
        );
      },
    );
  }

  // Товары в магазине
  Widget _buildProductsGrid() {
    return GridView.builder(
      padding: const EdgeInsets.all(8),
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 2, // 2 колонки
        mainAxisSpacing: 8,
        crossAxisSpacing: 8,
        childAspectRatio: 0.7, // Высокие карточки
      ),
      itemCount: 20,
      itemBuilder: (context, index) {
        final price = (index + 1) * 2500;
        final oldPrice = price + 1000;
        final discount = ((1000 / oldPrice) * 100).round();

        return Card(
          clipBehavior: Clip.antiAlias,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // Изображение с бейджем скидки
              Expanded(
                flex: 3,
                child: Stack(
                  fit: StackFit.expand,
                  children: [
                    Image.network(
                      'https://picsum.photos/200/200?random=${index + 50}',
                      fit: BoxFit.cover,
                    ),
                    Positioned(
                      top: 8,
                      left: 8,
                      child: Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 6,
                          vertical: 2,
                        ),
                        decoration: BoxDecoration(
                          color: Colors.red,
                          borderRadius: BorderRadius.circular(4),
                        ),
                        child: Text(
                          '-$discount%',
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 10,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ),
                    ),
                    Positioned(
                      top: 8,
                      right: 8,
                      child: Container(
                        padding: const EdgeInsets.all(4),
                        decoration: const BoxDecoration(
                          color: Colors.white,
                          shape: BoxShape.circle,
                        ),
                        child: const Icon(
                          Icons.favorite_border,
                          size: 18,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              // Информация о товаре
              Expanded(
                flex: 2,
                child: Padding(
                  padding: const EdgeInsets.all(8),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Товар ${index + 1}',
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(fontSize: 13),
                      ),
                      const Spacer(),
                      Row(
                        children: [
                          Text(
                            '$price ₸',
                            style: const TextStyle(
                              fontWeight: FontWeight.bold,
                              color: Colors.red,
                            ),
                          ),
                          const SizedBox(width: 4),
                          Text(
                            '$oldPrice ₸',
                            style: const TextStyle(
                              fontSize: 11,
                              color: Colors.grey,
                              decoration: TextDecoration.lineThrough,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 4),
                      Row(
                        children: [
                          const Icon(
                            Icons.star,
                            size: 14,
                            color: Colors.amber,
                          ),
                          const Text(
                            ' 4.8',
                            style: TextStyle(fontSize: 12),
                          ),
                          Text(
                            ' (${(index + 1) * 12})',
                            style: TextStyle(
                              fontSize: 12,
                              color: Colors.grey.shade600,
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';

