                      _buildPhysicsChip('Bouncing', 'iOS стиль'),
                      _buildPhysicsChip('Clamping', 'Android'),
                      _buildPhysicsChip('Never', 'Отключено'),
                      _buildPhysicsChip('Always', 'Всегда'),
