                      trailing: const Icon(Icons.chevron_right),
                    ),
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildPhysicsChip(String physics, String label) {
    final isSelected = _selectedPhysics == physics;
    return ChoiceChip(
      label: Text(label),
      selected: isSelected,
      onSelected: (selected) {
        if (selected) {
          setState(() => _selectedPhysics = physics);
        }
      },
    );
  }

  String _getPhysicsDescription() {
    switch (_selectedPhysics) {
      case 'Bouncing':
        return '🧊 Эффект "резинки" - контент пружинит на краях (как iOS)';
      case 'Clamping':
        return '🏖️ Контент останавливается на краях с эффектом свечения (как Android)';
      case 'Never':
        return '🔒 Прокрутка полностью отключена. Попробуйте - ничего не произойдет!';
      case 'Always':
        return '♾️ Всегда можно прокручивать, даже если контент помещается на экране';
      default:
        return '';
    }
  }
}

