import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatefulWidget {
  const MyApp({super.key});

  @override
  State<MyApp> createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  // Контроллер прокрутки
  final ScrollController _scrollController = ScrollController();

  // Показывать ли кнопку "Наверх"
  bool _showScrollToTop = false;

  // Текущая позиция для отображения
  double _scrollOffset = 0;

  @override
  void initState() {
    super.initState();

    // Слушаем изменения прокрутки
    _scrollController.addListener(_onScroll);
  }

  void _onScroll() {
    setState(() {
      _scrollOffset = _scrollController.offset;
      // Показываем кнопку если прокрутили больше 200 пикселей
      _showScrollToTop = _scrollController.offset > 200;
    });
  }

  // Прокрутка к началу
  void _scrollToTop() {
    _scrollController.animateTo(
      0,
      duration: const Duration(milliseconds: 500),
      curve: Curves.easeOut,
    );
  }

  // Прокрутка к концу
  void _scrollToBottom() {
    _scrollController.animateTo(
      _scrollController.position.maxScrollExtent,
      duration: const Duration(milliseconds: 500),
      curve: Curves.easeOut,
    );
  }

  // Прокрутка к определенному элементу
  void _scrollToItem(int index) {
    // Примерная высота элемента = 80
    _scrollController.animateTo(
      index * 80.0,
      duration: const Duration(milliseconds: 300),
      curve: Curves.easeInOut,
    );
  }

  @override
  void dispose() {
    // Не забываем освободить ресурсы!
    _scrollController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(
          title: const Text('ScrollController'),
          actions: [
            // Кнопка прокрутки вниз
            IconButton(
              icon: const Icon(Icons.arrow_downward),
              onPressed: _scrollToBottom,
              tooltip: 'К концу',
            ),
          ],
        ),
        body: Column(
          children: [
            // Панель информации
            Container(
              padding: const EdgeInsets.all(12),
              color: Colors.blue.shade50,
              child: Column(
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        'Позиция: ${_scrollOffset.toStringAsFixed(0)} px',
                        style: const TextStyle(fontWeight: FontWeight.bold),
                      ),
                      Text(
                        'Макс: ${_scrollController.hasClients ? _scrollController.position.maxScrollExtent.toStringAsFixed(0) : "?"} px',
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  // Прогресс-бар прокрутки
                  LinearProgressIndicator(
                    value: _scrollController.hasClients && 
                           _scrollController.position.maxScrollExtent > 0
                        ? _scrollOffset / _scrollController.position.maxScrollExtent
                        : 0,
                    backgroundColor: Colors.grey.shade300,
                  ),
                ],
              ),
            ),

            // Быстрые переходы
            SizedBox(
              height: 50,
              child: ListView(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
                children: List.generate(
                  10,
                  (index) => Padding(
                    padding: const EdgeInsets.only(right: 8),
                    child: ActionChip(
                      label: Text('К #${(index + 1) * 5}'),
                      onPressed: () => _scrollToItem((index + 1) * 5 - 1),
                    ),
                  ),
                ),
              ),
            ),

            // Основной список
            Expanded(
              child: ListView.builder(
                controller: _scrollController, // Привязываем контроллер!
                padding: const EdgeInsets.all(8),
                itemCount: 50,
                itemBuilder: (context, index) {
                  return Card(
                    color: index % 5 == 0 
                        ? Colors.blue.shade50 
                        : null,
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundColor: Colors.primaries[index % Colors.primaries.length],
                        child: Text(
                          '${index + 1}',
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 12,
                          ),
                        ),
                      ),
                      title: Text('Элемент ${index + 1}'),
                      subtitle: Text(
                        index % 5 == 0 
                            ? '⭐ Каждый 5-й элемент выделен'
                            : 'Прокручивайте список',
                      ),
                    ),
                  );
                },
              ),
            ),
          ],
        ),

        // Кнопка "Наверх"
        floatingActionButton: AnimatedOpacity(
          opacity: _showScrollToTop ? 1.0 : 0.0,
          duration: const Duration(milliseconds: 200),
          child: FloatingActionButton(
            onPressed: _showScrollToTop ? _scrollToTop : null,
            child: const Icon(Icons.arrow_upward),
          ),
        ),
      ),
    );
  }
}

