    // Имитация загрузки
    await Future.delayed(const Duration(seconds: 1));
    // В реальном приложении здесь загрузка данных с сервера
  }

  @override
  Widget build(BuildContext context) {
    // Фильтруем новости по категории
    final filteredNews = _selectedCategory == 0
        ? _news
        : _news.where((n) => n['category'] == _selectedCategory).toList();

    return Scaffold(
      appBar: AppBar(
        title: const Text('Новости'),
        actions: [
          IconButton(
            icon: const Icon(Icons.search),
            onPressed: () {},
          ),
          IconButton(
            icon: const Icon(Icons.notifications_outlined),
            onPressed: () {},
          ),
        ],
      ),
      body: Column(
        children: [
          // Горизонтальный список категорий
          SizedBox(
            height: 50,
            child: ListView.builder(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 8),
              itemCount: _categories.length,
              itemBuilder: (context, index) {
                final isSelected = _selectedCategory == index;
                return Padding(
                  padding: const EdgeInsets.only(right: 8),
                  child: ChoiceChip(
                    label: Text(_categories[index]),
                    selected: isSelected,
                    onSelected: (selected) {
                      if (selected) {
                        setState(() => _selectedCategory = index);
                      }
                    },
                  ),
                );
              },
            ),
          ),

          // Вертикальный список новостей с pull-to-refresh
          Expanded(
            child: RefreshIndicator(
              onRefresh: _refresh,
              child: ListView.builder(
                controller: _scrollController,
                padding: const EdgeInsets.all(8),
                itemCount: filteredNews.length,
                itemBuilder: (context, index) {
                  final news = filteredNews[index];

                  // Первая новость - большая карточка
                  if (index == 0) {
                    return _buildFeaturedCard(news);
                  }

                  // Остальные - компактные карточки
                  return _buildNewsCard(news);
                },
              ),
            ),
          ),
        ],
      ),

      // Кнопка "Наверх"
      floatingActionButton: _showScrollToTop
          ? FloatingActionButton.small(
              onPressed: () {
                _scrollController.animateTo(
                  0,
                  duration: const Duration(milliseconds: 500),
                  curve: Curves.easeOut,
                );
              },
              child: const Icon(Icons.arrow_upward),
            )
          : null,
    );
  }

